import React, { useState, useMemo } from 'react';

// Create the ExpensiveComputationDemo component here
const ExpensiveComputationDemo = () => {
    // Initialize state for the counter here
    const [counter, setCounter] = useState(0);
    // Initialize state for the multiplier here
    const [multiplier, setMultiplier] = useState(1);

    // Define the expensive computation function here
    const expensiveCalculation = (num) => {
        console.log('Running expensive calculation...');
        let result = 0;
        for (let i = 0; i < 1000000000; i++) {
            result += num;
        }
        return result;
    };

    // Use useMemo to memoize the expensive computation here
    const computedValue = useMemo(() => expensiveCalculation(multiplier), [multiplier]);

    // Define the incrementCount handler here
    const incrementCount = () => {
        setCounter(counter + 1);
    };

    // Define the updateMultiplier handler here
    const updateMultiplier = (e) => {
        setMultiplier(Number(e.target.value));
    };

    return (
        <div>
            {/* Add counter display and increment button here */}
            <p>Counter: {counter}</p>
            <button onClick={incrementCount}>Increment Counter</button>
            {/* Add multiplier input and computed value display here */}
        </div>
    );
};
